const CACHE='arianas-shop-v5';const FILES=["/", "/index.html", "/style.css", "/app.js", "/privacy.js", "/privacy.html", "/personal-data.html", "/cookies.html", "/terms.html", "/assets/bakery.webp", "/assets/collections.webp", "/assets/tea.webp", "/assets/gathering.webp", "/assets/baking.webp", "/assets/icon-192.png", "/assets/icon-512.png", "/manifest.webmanifest"];self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)))});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('arianas-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&FILES.includes(new URL(e.request.url).pathname)){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)))}return r}).catch(()=>caches.match(e.request).then(r=>r||Response.error())))});
